def parse_duration(s: str) -> int:
    seconds = 0
    for unit in s.split():
        if 'h' in unit:
            hours = int(unit[:-1])
            seconds += hours * 3600
        elif 'm' in unit:
            minutes = int(unit[:-1])
            seconds += minutes * 60
        else:
            seconds += int(unit)
    return seconds
